// The measurement, sandbox, records and agent helper functions against outputs recorded from the Python reference:
//   fixtures/sandbox-python.json  copied unchanged from valun-app/test/fixtures (generated by valun-open sandbox.py)
//   fixtures/python-parity.json   generated by fixtures/generate_python_fixtures.py (CPython 3.14)
// the constants both clients must hold identically, and the check that the fixtures were generated from the Python
// sources as they are now (when python/src is present).
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import {test} from 'node:test';
import {fileURLToPath} from 'node:url';
import * as api from '../src/index.js';
import {FileStore} from '../src/file-store.js';
import {PyError, int, repr, typeName} from '../src/py.js';
import {FIX, PARITY as P} from './agent-world.js';

const {ValunError, errorPayload, limitsBody, loosens, measure, owes, quoteLine, quoted, recentlyActive, records, sandbox, shown, termsText,
  verifyNote} = api;
const fixture = name => JSON.parse(fs.readFileSync(new URL(`./fixtures/${name}`, import.meta.url), 'utf8'));
const SANDBOX = fixture('sandbox-python.json');
const SCHEMAS = fixture('schemas-python.json');
const show = v => JSON.stringify(v)?.slice(0, 120);
/** What fn() returns, or what it throws, as the generator's outcome() records it (a ValunError's code and cause too). */
const outcome = fn => {
  try {
    return {value: fn()};
  } catch (e) {
    if (e instanceof ValunError) {
      const out = {raises: 'ValunError', code: e.code, message: e.message};
      if (Object.hasOwn(e.extra ?? {}, 'cause')) out.cause = e.extra.cause;
      return out;
    }
    return {raises: e.name, message: e.message};
  }
};
const resolveHost = measure.hostResolver(async h => {
  if (!Object.hasOwn(P.dns, h)) throw new Error('ENOTFOUND');
  return P.dns[h];
});

test('fixtures were generated from the Python sources as they are now (python/src/valun, LF line endings)', t => {
  const dir = fileURLToPath(new URL('../../python/src/valun/', import.meta.url));
  if (!fs.existsSync(dir)) return t.skip('python/src is not next to js/ (published package)');
  for (const f of [P, FIX, SCHEMAS]) {
    for (const [file, sha] of Object.entries(f.python_sources_sha256)) {
      const now = crypto.createHash('sha256').update(fs.readFileSync(dir + file, 'utf8').replace(/\r\n/g, '\n'), 'utf8').digest('hex');
      assert.equal(now, sha, `python/src/valun/${file} changed since the fixtures were generated: run python js/test/fixtures/generate_python_fixtures.py`);
    }
  }
  // the decision table novation_cases records comes from python/tests/test_novation.py
  const tests = fileURLToPath(new URL('../../python/tests/', import.meta.url));
  assert.ok(Object.keys(P.python_tests_sha256 ?? {}).length > 0, 'the generator records the test files it read');
  for (const [file, sha] of Object.entries(P.python_tests_sha256)) {
    const now = crypto.createHash('sha256').update(fs.readFileSync(tests + file, 'utf8').replace(/\r\n/g, '\n'), 'utf8').digest('hex');
    assert.equal(now, sha, `python/tests/${file} changed since the fixtures were generated: run python js/test/fixtures/generate_python_fixtures.py`);
  }
});

test('sandbox: text-stats, notary and extract_text identical to Python (sandbox-python.json, including Unicode edge cases)', () => {
  for (const s of SANDBOX.stats) {
    assert.deepEqual(sandbox.textStats(s.text), s.text_stats, `text-stats of ${show(s.text)}`);
    assert.deepEqual(sandbox.notary(s.text), s.notary, `notary of ${show(s.text)}`);
  }
  for (const e of SANDBOX.extract) assert.equal(sandbox.extractText(e.description), e.text, `extract from ${show(e.description)}`);
});

test('sandbox: more text-stats/notary, extract_text, render, parse_result, check_delivery and which_service cases', () => {
  for (const [text, stats, notary] of P.text_stats) {
    assert.deepEqual(sandbox.textStats(text), stats, show(text));
    assert.deepEqual(sandbox.notary(text), notary, show(text));
  }
  for (const [d, text] of P.extract_text) assert.equal(sandbox.extractText(d), text, show(d));
  for (const [service, result, text, out] of P.render) assert.equal(sandbox.render(service, result, text), out, service);
  for (const [content, result] of P.parse_result) assert.deepEqual(sandbox.parseResult(content), result, show(content));
  for (const [terms, content, out] of P.check_delivery) {
    const got = sandbox.checkDelivery(terms, content);
    assert.deepEqual(got, out, show(terms) + ' ' + show(content));
    assert.equal(JSON.stringify(got), JSON.stringify(out), 'key order');
  }
  for (const [terms, out] of P.which_service) assert.equal(sandbox.whichService(terms), out, show(terms));
});

test('sandbox: a delivery whose ```json block is not JSON throws, as Python raises (callers turn it into internal_error)', () => {
  const terms = {service: {title: 'notary', description: 'TEXT: abc'}};
  assert.throws(() => sandbox.checkDelivery(terms, '```json\n{"bytes": 3,\n```'), SyntaxError);
  assert.throws(() => sandbox.checkDelivery(terms, '```json\n[1, 2]\n```'), e => e.name === 'AttributeError');
  assert.throws(() => sandbox.checkDelivery(terms, '```json\n5\n```'), e => e.name === 'TypeError' && /not iterable/.test(e.message));
});

test('measure: word counts, links, hosts and numeric requirements identical to Python', () => {
  for (const [text, n] of P.word_count) assert.equal(measure.wordCount(text), n, show(text));
  for (const [text, out] of P.links) assert.deepEqual(measure.links(text), out, show(text));
  for (const [url, host] of P.hosts) assert.equal(measure.hostOf(url), host, url);
  for (const [text, req] of P.requirements) {
    assert.deepEqual(measure.requirements(text), req, show(text));
    assert.equal(JSON.stringify(measure.requirements(text)), JSON.stringify(req), 'key order');
  }
});

test('measure: measure() identical to Python, DNS answers from the same table (no network)', async () => {
  for (const c of P.measure) {
    const got = await measure.measure(c.text, c.terms, {checkHosts: c.check_hosts, resolveHost});
    assert.deepEqual(got, c.out, show(c.text));
    assert.equal(JSON.stringify(got), JSON.stringify(c.out), 'key order');
  }
});

test('measure: is_global of IPv4 and IPv6 addresses as Python 3.14 ipaddress decides it', () => {
  for (const [addr, global] of P.is_global) assert.equal(measure.isGlobalAddress(addr), global, addr);
  assert.throws(() => measure.isGlobalAddress('not an address'), TypeError);
  assert.throws(() => measure.isGlobalAddress('1:2:3:4:5:6:7:8:9'), TypeError);
  assert.throws(() => measure.isGlobalAddress('01.2.3.4'), TypeError);       // leading zeros are refused, as in Python
});

test('agent helpers: recently_active, limits_body, loosens, terms_text and error_payload identical to Python', () => {
  for (const [last, hours, joined, out] of P.recently_active) {
    assert.equal(recentlyActive(last, hours, joined, P.t0_ms), out, `${show(last)} (${hours} h, joined ${show(joined)})`);
  }
  for (const [args, out] of P.limits_body) assert.deepEqual(outcome(() => limitsBody(args)), out, show(args));
  for (const [cur, body, out] of P.loosens) assert.deepEqual(outcome(() => loosens(cur, body)), out, show([cur, body]));
  for (const [d, text] of P.terms_text) assert.equal(termsText(d), text, show(d));
  for (const [code, message, extra, out, outHint] of P.error_payload) {
    const e = new ValunError(code, message, 400, extra);
    assert.deepEqual(errorPayload(e), out, code);
    assert.equal(JSON.stringify(errorPayload(e)), JSON.stringify(out), 'key order');
    assert.deepEqual(errorPayload(e, 'do X'), outHint, code);
  }
  assert.deepEqual(errorPayload(new TypeError('boom')), {error: 'internal_error', message: 'TypeError: boom'});
  assert.deepEqual(errorPayload('thrown text'), {error: 'internal_error', message: 'Error: thrown text'});
});

test('Python semantics: int() and repr() of JSON values', () => {
  for (const [v, out] of P.int) assert.deepEqual(outcome(() => int(v)), out, show(v));
  for (const [v, out] of P.repr) assert.equal(repr(v), out, show(v));
});

test('approval text helpers: quoted (Python json.dumps, ASCII, compact), shown, quoteLine and owes identical to Python', () => {
  for (const [v, out] of P.quoted) assert.equal(quoted(v), out, show(v));
  for (const [v, out] of P.shown) assert.equal(shown(v), out, show(v));
  for (const [label, fields, out] of P.quote_line) assert.equal(quoteLine(label, fields), out, label);
  for (const [role, who, price, out] of P.owes) assert.equal(owes(role, who, price), out, role);
});

test('records.py step by step: every call gives the same outcome and leaves the same records (real signatures)', () => {
  const recs = {};
  const verify = (i, r, t, ts, sig) => verifyNote(i, r, t, ts, sig, P.nft, P.denomination);
  const broken = () => { throw new Error('verifier down'); };
  const camel = name => name.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
  for (const [i, step] of P.records.entries()) {
    const fn = records[camel(step.fn)];
    assert.equal(typeof fn, 'function', step.fn);
    const args = step.args.map(a => (['prior_problem', 'accept_prior'].includes(step.fn) && (a === 'verify' || a === 'broken')
      ? {verify, broken}[a] : a));
    const got = outcome(() => (['pair_key', 'edge_state'].includes(step.fn) ? fn(...args) : fn(recs, ...args)));
    assert.deepEqual(JSON.parse(JSON.stringify(got)), step.outcome, `step ${i}: ${step.fn}(${show(step.args)})`);
    assert.deepEqual(JSON.parse(JSON.stringify(recs)), step.records, `step ${i}: records after ${step.fn}`);
  }
  for (const [args, out] of P.verify_note) assert.equal(verifyNote(...args), out, show(args));
});

